<template>
  <section class="therapy-workspace">
    <header class="therapy-header">
      <div class="therapy-brand"><img v-if="productName" :src="AURICWELL_MARK_URL" :alt="productName" /><img v-else-if="branding?.logoUrl" :src="branding.logoUrl" alt="" /><div><strong>{{ productName || branding?.agencyName || 'Virtual office' }}</strong><small>{{ productName ? branding?.agencyName : 'Virtual care' }}</small></div></div>
      <span class="therapy-status">● In session</span><span class="therapy-clock">{{ elapsed }}</span>
      <button class="danger" @click="$emit('leave-request')">{{ isHost ? 'End session' : 'Leave session' }}</button>
    </header>
    <p v-if="error" role="alert">{{ error }} <button @click="refresh">Retry</button></p>
    <div class="therapy-layout" :class="{'has-share': shared && shared.payload.mode !== 'video'}">
      <div class="therapy-main">
        <div class="therapy-video"><slot name="video"><VideoSessionRoom ref="videoRef" v-bind="video" :hide-controls="true" :server-managed-end="true" :equal-tiles-when-remote="false" :is-host-or-cohost="isHost" :show-layout-controls="true" @connected="$emit('connected')" @disconnected="$emit('disconnected')" @leave-request="$emit('leave-request')" @meeting-ended="$emit('meeting-ended')" /></slot></div>
        <section v-if="shared && shared.payload.mode !== 'video'" class="therapy-shared" :aria-label="shared.payload.title || 'Shared tool'">
          <div class="shared-heading"><div><small>{{ shared.role==='client' ? 'SHARED BY CLIENT' : 'SHARED IN SESSION' }}</small><h2>{{ shared.payload.title || modeLabel(shared.payload.mode) }}</h2></div><button @click="save('share',{mode:'video'})">Close tool</button></div>
          <template v-if="shared.payload.mode === 'whiteboard'">
            <div class="draw-controls"><label>Ink <input v-model="ink" type="color" /></label><span>Draw together. Each stroke is saved with this session.</span></div>
            <svg class="whiteboard" viewBox="0 0 1000 700" role="img" aria-label="Shared drawing canvas" @pointerdown="beginStroke" @pointermove="moveStroke" @pointerup="endStroke" @pointercancel="endStroke">
              <polyline v-for="a in drawings" :key="a.id" :points="a.payload.points.map(p=>p.join(',')).join(' ')" :stroke="a.payload.color" fill="none" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" />
              <polyline :points="stroke.map(p=>p.join(',')).join(' ')" :stroke="ink" fill="none" stroke-width="4" stroke-linecap="round" />
            </svg>
          </template>
          <template v-else-if="['pdf','book'].includes(shared.payload.mode)"><SharedSessionPdf v-if="shared.payload.document" :key="shared.id" :data-url="shared.payload.document" @page-change="page=$event;markViewed()" /><a v-else :href="shared.payload.url" target="_blank" rel="noopener noreferrer" @click="markViewed">Open shared document ↗</a></template>
          <template v-else-if="shared.payload.mode === 'media'"><p class="muted">Open the video in a separate tab, or use Share screen to watch together.</p><a :href="shared.payload.url" target="_blank" rel="noopener noreferrer" @click="markViewed">Open {{ shared.payload.title || 'shared video' }} ↗</a></template>
          <template v-else-if="['assessment','activity'].includes(shared.payload.mode)"><form class="response-form" @submit.prevent="submitAnswers"><p>{{ shared.payload.description }}</p><div v-if="shared.payload.mode==='activity'" class="feelings-grid"><button v-for="feeling in feelings" :key="feeling.label" type="button" :aria-pressed="answers[0]===feeling.label" @click="answers[0]=feeling.label"><span>{{ feeling.emoji }}</span>{{ feeling.label }}</button></div><label v-for="(q,i) in shared.payload.questions" :key="i">{{ q }}<textarea v-model="answers[i]" required maxlength="4000" rows="3" /></label><button class="primary" :disabled="saving">Save responses</button><p role="status">{{ savedMessage }}</p></form></template>
          <template v-else-if="shared.payload.mode === 'treatment'"><p v-for="goal in shared.payload.goals" :key="goal.id">{{ goal.text }}</p><form v-if="!isHost && identified" @submit.prevent="saveRating"><label>How would you rate your progress? <select v-model.number="rating"><option v-for="n in 10" :key="n" :value="n">{{ n }} / 10</option></select></label><button class="primary">Save my rating</button><p role="status">{{ savedMessage }}</p></form></template>
          <a v-else :href="shared.payload.url" target="_blank" rel="noopener noreferrer" @click="markViewed">Open {{ shared.payload.title || 'shared resource' }} ↗</a>
        </section>
        <nav class="therapy-dock" aria-label="Session controls">
          <button @click="controls()?.toggleMic()"><Mic :size="21" />{{ controls()?.publishAudio === false ? 'Unmute' : 'Mute' }}</button>
          <button @click="controls()?.toggleCamera()"><Video :size="21" />{{ controls()?.publishVideo === false ? 'Start video' : 'Stop video' }}</button>
          <button @click="controls()?.toggleScreenShare()"><ScreenShare :size="21" />Share screen</button>
          <button @click="save('share',{mode:'whiteboard',title:'Our whiteboard'})"><Pencil :size="21" />Whiteboard</button>
          <button @click="panel=panel==='chat'?'tools':'chat'"><MessageCircle :size="21" />Chat</button>
          <button @click="panel=panel==='saved'?'tools':'saved'"><FolderOpen :size="21" />Session files</button>
        </nav>
        <slot />
      </div>
      <aside class="therapy-side">
        <nav class="side-tabs"><button @click="panel='tools'">Share</button><button @click="panel='chat'">Chat</button><button @click="panel='saved'">Saved</button></nav>
        <template v-if="panel==='tools'">
          <h2>Share in this session</h2><p class="muted">Tools and resources for your time together.</p>
          <button v-for="tool in tools" :key="tool.mode" class="tool-card" @click="selectTool(tool.mode)"><component :is="tool.icon" :size="23" /><span><strong>{{ tool.label }}</strong><small>{{ tool.hint }}</small></span><ChevronRight :size="18" /></button>
          <form v-if="draftMode" class="share-form" @submit.prevent="shareDraft">
            <h3>{{ modeLabel(draftMode) }}</h3><label>Title<input v-model="draftTitle" maxlength="150" required /></label>
            <template v-if="['assessment','activity'].includes(draftMode)"><label>Questions (one per line)<textarea v-model="draftQuestions" rows="5" required maxlength="15000" /></label></template>
            <label v-else-if="draftMode==='treatment'">Treatment plan<select v-model="planId" required><option value="">Choose a treatment plan</option><option v-for="plan in treatmentPlans" :key="plan.id" :value="plan.id">{{ plan.title }} · {{ plan.status }}</option></select></label>
            <template v-else><label>HTTPS link<input v-model="draftUrl" type="url" :required="!documentData" /></label><label v-if="['pdf','book'].includes(draftMode)">Or attach a PDF (up to 2 MB)<input type="file" accept="application/pdf" @change="readDocument" /></label></template>
            <button class="primary" :disabled="saving">Share with session</button><button type="button" @click="draftMode=''">Cancel</button>
          </form>
        </template>
        <template v-else-if="panel==='saved'"><h2>Session files</h2><p class="muted">Shared content and completed work stay with this session.</p><article v-for="a in savedArtifacts" :key="a.id" class="saved-item"><strong>{{ a.payload.title || modeLabel(a.payload.mode) || a.type }}</strong><small>{{ a.role }} · {{ new Date(a.createdAt).toLocaleTimeString() }}</small><p v-if="a.type==='rating'">Progress: {{ a.payload.value }} / 10</p><p v-for="(answer,i) in a.payload.answers || []" :key="i">{{ answer }}</p><a v-if="a.payload.document" :href="a.payload.document" :download="`${a.payload.title || 'attachment'}.pdf`" @click.prevent="downloadPdf(a)">Download PDF</a><button v-if="a.type==='drawing'" @click="downloadDrawing(a)">Download drawing</button></article></template>
        <template v-else><h2>Chat</h2><div class="therapy-messages" aria-live="polite"><article v-for="m in chats" :key="m.id"><small>{{ m.role }}</small><p>{{ m.payload.text }}</p></article></div><form class="chat-form" @submit.prevent="sendChat"><input v-model="chat" maxlength="4000" placeholder="Type a message…" aria-label="Message" /><button class="primary" :disabled="saving || !chat.trim()">Send</button></form></template>
      </aside>
    </div>
  </section>
</template>
<script setup>
import { AURICWELL_MARK_URL } from '../../constants/auricwellBrand';
import {defineAsyncComponent,computed,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import {Mic,Video,ScreenShare,Pencil,MessageCircle,FolderOpen,FileText,Gamepad2,Play,Link,BookOpen,ClipboardList,Heart,ChevronRight} from '@lucide/vue';
import VideoSessionRoom from '../video/VideoSessionRoom.vue';
const SharedSessionPdf=defineAsyncComponent(()=>import('./SharedSessionPdf.vue'));
const props=defineProps({video:{type:Object,default:()=>({})},isHost:Boolean,identified:Boolean,branding:Object,productName:{type:String,default:'AuricWell'},request:{type:Function,required:true},videoControl:Function});
defineEmits(['connected','disconnected','leave-request','meeting-ended']);
const videoRef=ref(null),artifacts=ref([]),error=ref(''),saving=ref(false),panel=ref(props.isHost?'chat':'tools'),chat=ref(''),draftMode=ref(''),draftTitle=ref(''),draftUrl=ref(''),draftQuestions=ref(''),documentData=ref(''),planId=ref(''),treatmentPlans=ref([]),page=ref(1),answers=ref([]),rating=ref(5),savedMessage=ref(''),ink=ref('#2563eb'),stroke=ref([]),now=ref(Date.now());
const started=Date.now();let poll,clock,drawing=false,polling=false,cursor=0;
const controls=()=>props.videoControl?.() || videoRef.value;
const elapsed=computed(()=>{const s=Math.floor((now.value-started)/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;});
const feelings=[{emoji:'😊',label:'Happy'},{emoji:'😌',label:'Calm'},{emoji:'😔',label:'Sad'},{emoji:'😠',label:'Angry'},{emoji:'😟',label:'Worried'},{emoji:'🌟',label:'Proud'}];
const tools=computed(()=>[{mode:'screen',label:'Share screen',hint:'Show your screen',icon:ScreenShare},{mode:'whiteboard',label:'Whiteboard',hint:'Draw and reflect together',icon:Pencil},{mode:'pdf',label:'Handout / PDF',hint:'Share a worksheet or document',icon:FileText},{mode:'activity',label:'Game / Activity',hint:'Explore feelings and coping skills',icon:Gamepad2},{mode:'media',label:'YouTube / Video',hint:'Watch a video together',icon:Play},{mode:'book',label:'Book',hint:'Read and discuss together',icon:BookOpen},{mode:'assessment',label:'Assessment / Questionnaire',hint:'Complete and save responses',icon:ClipboardList},{mode:'resource',label:'Resource link',hint:'Share a helpful website',icon:Link},...(props.identified&&props.isHost?[{mode:'treatment',label:'Treatment plan',hint:'Share goals for client self-rating',icon:Heart}]:[])]);
const modeLabel=mode=>tools.value.find(t=>t.mode===mode)?.label || mode || '';
const shared=computed(()=>artifacts.value.filter(a=>a.type==='share').at(-1));
const chats=computed(()=>artifacts.value.filter(a=>a.type==='chat'));
const savedArtifacts=computed(()=>artifacts.value.filter(a=>!['chat','download'].includes(a.type)&&!(a.type==='share'&&a.payload.mode==='video')&&(a.type!=='drawing'||!artifacts.value.some(other=>other.type==='drawing'&&other.payload.shareId===a.payload.shareId&&other.id>a.id))).slice().reverse());
const drawings=computed(()=>artifacts.value.filter(a=>a.type==='drawing'&&a.payload.shareId===shared.value?.id));

watch(()=>shared.value?.id,()=>{page.value=1;answers.value=[];savedMessage.value='';});
async function refresh(){if(polling)return;polling=true;try{let more=true;while(more){const data=await props.request(`?afterId=${cursor}`,{method:'GET'});const known=new Set(artifacts.value.map(a=>a.id));artifacts.value.push(...(data.artifacts||[]).filter(a=>!known.has(a.id)));artifacts.value.sort((a,b)=>a.id-b.id);cursor=data.nextCursor||cursor;more=!!data.hasMore;}error.value='';}catch(e){error.value=e.response?.data?.error?.message||e.message;}finally{polling=false;}}
async function save(type,payload){if(saving.value)return false;saving.value=true;error.value='';try{const result=await props.request('',{method:'POST',body:{type,payload}});if(result.artifact&&!artifacts.value.some(a=>a.id===result.artifact.id))artifacts.value.push(result.artifact);return true;}catch(e){error.value=e.response?.data?.error?.message||e.message;return false;}finally{saving.value=false;}}
async function sendChat(){if(await save('chat',{text:chat.value.trim()}))chat.value='';}
async function selectTool(mode){if(mode==='screen')return controls()?.toggleScreenShare();if(mode==='whiteboard')return save('share',{mode,title:'Our whiteboard'});if(mode==='treatment'){try{treatmentPlans.value=(await props.request('/treatment-plans',{method:'GET'})).plans;}catch(e){error.value=e.response?.data?.error?.message||e.message;return;}}draftMode.value=mode;draftTitle.value=mode==='activity'?'Feelings explorer':modeLabel(mode);draftUrl.value='';documentData.value='';draftQuestions.value=mode==='activity'?'How are you feeling today?\nWhat helps you feel calm?\nWhat is one thing you can try this week?':'';}
async function shareDraft(){const payload={mode:draftMode.value,title:draftTitle.value};if(draftMode.value==='treatment')payload.planId=Number(planId.value);else if(['assessment','activity'].includes(draftMode.value))payload.questions=draftQuestions.value.split('\n').map(q=>q.trim()).filter(Boolean);else if(documentData.value)payload.document=documentData.value;else payload.url=draftUrl.value;if(await save('share',payload))draftMode.value='';}
function readDocument(e){const f=e.target.files?.[0];if(!f)return;if(f.size>2*1024*1024){error.value='Choose a PDF under 2 MB.';return;}const reader=new FileReader();reader.onload=()=>{documentData.value=reader.result;};reader.readAsDataURL(f);}
async function submitAnswers(){if(await save('response',{shareId:shared.value.id,answers:shared.value.payload.questions.map((_,i)=>answers.value[i]||'')}))savedMessage.value='Responses saved to this session.';}
async function saveRating(){if(await save('rating',{shareId:shared.value.id,value:rating.value}))savedMessage.value='Your rating is saved.';}
function markViewed(){return save('viewed',{shareId:shared.value.id,page:page.value});}
function point(e){const svg=e.currentTarget,p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const local=p.matrixTransform(svg.getScreenCTM().inverse());return [Math.round(Math.max(0,Math.min(1000,local.x))),Math.round(Math.max(0,Math.min(700,local.y)))];}
function beginStroke(e){if(saving.value)return;drawing=true;e.currentTarget.setPointerCapture(e.pointerId);stroke.value=[point(e)];}
function moveStroke(e){if(drawing&&stroke.value.length<2000)stroke.value.push(point(e));}
async function endStroke(){if(!drawing)return;drawing=false;const points=stroke.value.map(p=>[...p]);if(points.length===1)points.push(points[0]);await save('drawing',{shareId:shared.value.id,color:ink.value,points});stroke.value=[];}
async function downloadPdf(a){if(!await recordDownload(a.id))return;const link=document.createElement('a');link.href=a.payload.document;link.download=`${a.payload.title || 'attachment'}.pdf`;link.click();}
async function recordDownload(artifactId){try{await props.request('/download',{method:'POST',body:{artifactId}});return true;}catch(e){error.value=e.response?.data?.error?.message||e.message;return false;}}
async function downloadDrawing(a){if(!await recordDownload(a.id))return;const strokes=artifacts.value.filter(item=>item.type==='drawing'&&item.payload.shareId===a.payload.shareId);const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 700">${strokes.map(item=>`<polyline fill="none" stroke="${item.payload.color}" stroke-width="4" points="${item.payload.points.map(p=>p.join(',')).join(' ')}"/>`).join('')}</svg>`;const u=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));const link=document.createElement('a');link.href=u;link.download='session-drawing.svg';link.click();URL.revokeObjectURL(u);}
onMounted(()=>{refresh();poll=setInterval(refresh,3000);clock=setInterval(()=>now.value=Date.now(),1000);});
onBeforeUnmount(()=>{clearInterval(poll);clearInterval(clock);});
defineExpose({getTranscriptionStream:()=>controls()?.getTranscriptionStream?.()});
</script>
<style scoped>
