y-shared{background:white;border:1px solid #e3e9f0;border-radius:16px;margin-top:14px;padding:18px}.shared-heading{display:flex;align-items:center;justify-content:space-between;gap:10px}.shared-heading small{color:#8592a4;font-size:10px;letter-spacing:.12em}.shared-heading h2{margin:6px 0 14px;font-size:21px}.whiteboard{width:100%;background:#fff;touch-action:none;border:1px solid #e2e8f0;border-radius:12px}.draw-controls{display:flex;align-items:center;gap:16px;font-size:12px;color:#64748b;margin:8px 0}.shared-document{width:100%;height:540px}.therapy-shared iframe,.therapy-shared video{width:100%;aspect-ratio:16/9;border:0}.page-controls{display:flex;justify-content:center;align-items:center;gap:14px;margin-top:10px}.therapy-workspace label{display:flex;flex-direction:column;gap:8px;font-size:13px;margin:12px 0}.therapy-workspace input,.therapy-workspace textarea,.therapy-workspace select{box-sizing:border-box;width:100%;border:1px solid #dce5eb;border-radius:9px;padding:10px;background:white;color:#17243b;font:inherit}.therapy-workspace input[type=color]{width:50px;padding:3px}.therapy-messages article{padding:12px;background:#f1f6fa;border-radius:12px;margin:12px 0;overflow-wrap:anywhere}.therapy-messages small,.saved-item small{color:#738297;font-size:11px;display:block}.therapy-messages p{margin:5px 0;font-size:14px}.chat-form{display:flex;gap:8px;position:sticky;bottom:0;background:white;padding:10px 0}.saved-item{padding:14px 0;border-bottom:1px solid #e9eef3;font-size:13px;overflow-wrap:anywhere}[role=alert]{color:#ad2434}@container(min-width:1300px){.has-share .therapy-main{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px}.has-share .therapy-video{height:65vh}.has-share .therapy-shared{margin:0}.has-share .therapy-dock{grid-column:1/-1}}@media(max-width:850px){.therapy-layout{grid-template-columns:1fr}.therapy-header{gap:8px;flex-wrap:wrap}.therapy-status{display:none}.therapy-workspace{padding:12px}.therapy-side{max-height:none}.therapy-video{height:55vh}.therapy-dock{gap:6px}.therapy-dock button{min-width:64px;padding:9px}.shared-document{height:420px}}
.feelings-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:20px 0}.feelings-grid button{background:#ecf8f2;border:2px solid transparent;display:flex;align-items:center;flex-direction:column;gap:12px;padding:22px 12px;font-weight:600}.feelings-grid button:nth-child(2n){background:#edf4fc}.feelings-grid button:nth-child(3n){background:#fff3e4}.feelings-grid button[aria-pressed=true]{border-color:#087f5b}.feelings-grid span{font-size:34px}</style>
